@using Umbraco.Extensions
@using Umbraco.Cms.Web.Common.PublishedModels
@using Umbraco.Cms.Web.Common.Views
@using Umbraco.Cms.Core.Models.PublishedContent
@using Microsoft.AspNetCore.Html
@addTagHelper *, Microsoft.AspNetCore.Mvc.TagHelpers

@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage<ContentModels.BlogPost>
@using ContentModels = Umbraco.Cms.Web.Common.PublishedModels;
@{
    Layout = null;
}
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>@Model.Value("title")</title>
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
</head>
<body class="bg-white">
    <header class="bg-gray-900 text-white py-12">
        <div class="container mx-auto px-4">
            @if (Model.Parent() != null)
            {
                <a href="@Model.Parent().Url()" class="text-gray-400 hover:text-white text-lg">← Back to Blog</a>
            }
            <h1 class="text-4xl font-bold mt-4">@Model.Value("title")</h1>
        </div>
    </header>
    <main class="container mx-auto px-4 py-12">
        <article class="prose prose-lg max-w-3xl mx-auto">
            @await Html.GetBlockGridHtmlAsync(Model, "blocks")
            <div class="mt-8 pt-8 border-t">
                @Html.Raw(Model.Value("content")?.ToString())
            </div>
        </article>
    </main>
    <script type="module" src="~/dist/main.js" asp-append-version="true"></script>
</body>
</html>

@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage<BlockGridItem<Umbraco.Cms.Web.Common.PublishedModels.RichTextBlock>>
@{
    var model = new RichTextBlockModel
    {
        Content = Model.Content.Content?.ToString()
    };
}
@await Component.InvokeAsync("RichTextBlock", new { model })

@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage<BlockGridItem<Umbraco.Cms.Web.Common.PublishedModels.ImageBlock>>
@{
